
.tri-status {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  overflow: hidden;
  border: 1px solid rgba(40, 44, 52, 0.14);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.96), rgba(247, 249, 248, 0.94)),
    radial-gradient(circle at top left, rgba(180, 79, 95, 0.12), transparent 38%),
    radial-gradient(circle at bottom right, rgba(95, 102, 179, 0.12), transparent 42%);
  color: #273036;
  font-family:
    Inter, 'Noto Sans SC', 'Microsoft YaHei', sans-serif;
  box-shadow: 0 10px 26px rgba(34, 38, 42, 0.1);
}

.status-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 16px 12px;
  border-bottom: 1px solid rgba(39, 48, 54, 0.1);
}

.kicker {
  margin: 0 0 4px;
  color: #69757d;
  font-size: 11px;
}

h1 {
  margin: 0;
  font-size: 18px;
  line-height: 1.35;
  font-weight: 700;
}

.time-place {
  display: grid;
  gap: 4px;
  min-width: 96px;
  text-align: right;
  color: #69757d;
  font-size: 11px;
}

.time-place strong {
  color: #273036;
  font-size: 17px;
  line-height: 1;
}

.world-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 16px;
  background: rgba(255, 255, 255, 0.58);
  color: #4b585f;
  font-size: 12px;
}

.mood {
  flex: 0 0 auto;
  border-radius: 999px;
  padding: 4px 9px;
  font-weight: 700;
}

.mood-calm {
  background: rgba(71, 136, 111, 0.14);
  color: #36725d;
}

.mood-soft {
  background: rgba(210, 138, 34, 0.16);
  color: #986016;
}

.mood-hot {
  background: rgba(180, 79, 95, 0.16);
  color: #9c3c4d;
}

.user-band {
  display: grid;
  grid-template-columns: minmax(130px, 0.8fr) minmax(0, 1.4fr);
  gap: 12px;
  padding: 12px 16px;
  border-top: 1px solid rgba(39, 48, 54, 0.08);
  border-bottom: 1px solid rgba(39, 48, 54, 0.08);
}

.user-band div {
  display: grid;
  gap: 3px;
}

.label {
  color: #69757d;
  font-size: 11px;
}

.user-band strong {
  font-size: 14px;
}

.user-band p,
.rival-side p {
  margin: 0;
  color: #4b585f;
  font-size: 12px;
  line-height: 1.45;
}

.rivals {
  display: grid;
}

.rival-row {
  display: grid;
  grid-template-columns: minmax(128px, 0.9fr) minmax(0, 1.35fr);
  gap: 14px;
  padding: 12px 16px;
  border-top: 1px solid rgba(39, 48, 54, 0.08);
}

.name-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.name-line strong {
  font-size: 15px;
}

.name-line span {
  color: #69757d;
  font-size: 11px;
}

.meter {
  position: relative;
  width: 100%;
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(39, 48, 54, 0.1);
}

.meter i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}

.rival-side {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.rival-side span {
  font-size: 12px;
  font-weight: 700;
}

@media (max-width: 520px) {
  .status-head,
  .user-band,
  .rival-row {
    grid-template-columns: 1fr;
  }

  .status-head {
    display: grid;
  }

  .time-place {
    min-width: 0;
    text-align: left;
  }

  .rival-row {
    gap: 8px;
  }
}
